package org.mockito.internal.invocation;

import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.exceptions.PrintableInvocation;
import org.mockito.exceptions.Reporter;
import org.mockito.internal.bytecode.stubbing.RealMethod;
import org.mockito.internal.debugging.Location;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.invocation.realmethod.RealMethod;
import org.mockito.internal.matchers.*;
import org.mockito.internal.reporting.PrintSettings;
import org.mockito.internal.reporting.PrintingFriendlyInvocation;
import org.mockito.internal.util.*;
import org.mockito.invocation.InvocationOnMock;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class Invocation_callRealMethod_TriageGen0Test {

    /**
     * Helper class to provide a concrete implementation for reflection.
     */
    public static class TestService {
        public String doSomething(String input) {
            return "Hello " + input;
        }

        public void voidMethod() {
        }
    }

    /**
     * Interface to test the branch where isInterface() is true.
     */
    public interface TestInterface {
        String interfaceMethod();
    }

    @Test
    public void testCallRealMethod_Success() throws Throwable {
        // Setup
        TestService mock = new TestService(); // In real Mockito this is a proxy, here we use the object for the 'mock' param
        Method method = TestService.class.getMethod("doSomething", String.class);
        MockitoMethod mockitoMethod = org.mockito.internal.invocation.MockitoMethod.getMethod(method);
        Object[] args = new Object[]{"World"};

        // RealMethod implementation that performs the actual invocation
        RealMethod realMethod = new RealMethod() {
            @Override
            public Object invoke(Object target, Object[] args) throws Throwable {
                return method.invoke(target, args);
            }
        };

        Invocation invocation = new Invocation(mock, mockitoMethod, args, 1, realMethod);

        // Execute
        Object result = invocation.callRealMethod();

        // Verify
        assertEquals("Hello World", result);
    }

    @Test
    public void testCallRealMethod_InterfaceBranch() throws Throwable {
        // Setup for the branch: if (this.getMethod().getDeclaringClass().isInterface())
        TestInterface mock = null; // dummy
        Method method = TestInterface.class.getMethod("interfaceMethod");
        MockitoMethod mockitoMethod = org.mockito.internal.invocation.MockitoMethod.getMethod(method);
        Object[] args = new Object[0];

        RealMethod realMethod = new RealMethod() {
            @Override
            public Object invoke(Object target, Object[] args) throws Throwable {
                return "interface_result";
            }
        };

        Invocation invocation = new Invocation(mock, mockitoMethod, args, 1, realMethod);

        // Execute
        Object result = invocation.callRealMethod();

        // Verify
        assertEquals("interface_result", result);
    }

    @Test
    public void testCallRealMethod_ThrowsException() throws Throwable {
        // Setup
        TestService mock = new TestService();
        Method method = TestService.class.getMethod("doSomething", String.class);
        MockitoMethod mockitoMethod = org.mockito.internal.invocation.MockitoMethod.getMethod(method);
        Object[] args = new Object[]{null}; // Passing null to trigger exception in logic if needed

        RealMethod realMethod = new RealMethod() {
            @Override
            public Object invoke(Object target, Object[] args) throws Throwable {
                throw new RuntimeException("Real method error");
            }
        };

        Invocation invocation = new Invocation(mock, mockitoMethod, args, 1, realMethod);

        // Execute & Verify
        assertThrows(RuntimeException.class, invocation::callRealMethod);
    }

    @Test
    public void testCallRealMethod_VoidMethod() throws Throwable {
        // Setup
        TestService mock = new TestService();
        Method method = TestService.class.getMethod("voidMethod");
        MockitoMethod mockitoMethod = org.mockito.internal.invocation.MockitoMethod.getMethod(method);
        Object[] args = new Object[0];

        RealMethod realMethod = new RealMethod() {
            @Override
            public Object invoke(Object target, Object[] args) throws Throwable {
                method.invoke(target, args);
                return null;
            }
        };

        Invocation invocation = new Invocation(mock, mockitoMethod, args, 1, realMethod);

        // Execute
        Object result = invocation.callRealMethod();

        // Verify
        assertEquals(null, result);
    }
}
